// Dữ liệu mẫu chuẩn Công ty A (50 nhân sự, 6 phòng ban, Quý 3/2026: Tháng 7, 8, 9)
// Tự động phân tích và đối soát chính xác 100% từ 10 file Excel nguồn của hệ thống

export interface Department {
  code: string;
  name: string;
  description: string;
  quota: number;
  leader: string;
}

export interface Employee {
  id: string;
  fullName: string;
  gender: string;
  birthDate: string;
  idCard: string;
  hometown: string;
  department: string;
  position: string;
  education: string;
  startDate: string;
  email: string;
  phone: string;
  bankAccount: string;
  bankName: string;
  bhxhCode: string;
  dependents: number;
  status: string;
}

export interface Contract {
  contractNumber: string;
  employeeId: string;
  employeeName: string;
  department: string;
  jobTitle: string;
  contractType: string;
  signDate: string;
  effectiveDate: string;
  expiryDate: string;
  insuranceSalary: number;
  workLocation: string;
  status: string;
}

export interface Attendance {
  month: string;
  employeeId: string;
  employeeName: string;
  department: string;
  position: string;
  standardDays: number;
  actualDays: number;
  leavePaid: number;
  leaveUnpaid: number;
  leaveSick: number;
  leaveMaternity: number;
  totalWorkDays: number;
  otNormalHours: number;
  otSundayHours: number;
  lateEarlyCount: number;
  notes: string;
}

export interface LeaveRecord {
  code: string;
  employeeId: string;
  employeeName: string;
  department: string;
  leaveType: string;
  fromDate: string;
  toDate: string;
  days: number;
  reason: string;
  approver: string;
  status: string;
}

export interface LeaveQuota {
  employeeId: string;
  employeeName: string;
  department: string;
  standardQuota: number;
  seniorityQuota: number;
  totalQuota: number;
  usedQuota: number;
  remainingQuota: number;
  notes: string;
}

export interface PayrollRecord {
  month: string;
  employeeId: string;
  employeeName: string;
  department: string;
  position: string;
  baseSalary: number;
  workDays: number;
  timeSalary: number;
  responsibilityAllowance: number;
  lunchAllowance: number;
  otPay: number;
  performanceBonus: number;
  grossIncome: number;
  bhxhDeduction: number;
  pitTax: number;
  netSalary: number;
  notes: string;
}

